CREATE TABLE `system_integration_idempotency` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `integration_id` BIGINT UNSIGNED NOT NULL, `event_key` VARCHAR(180) NOT NULL, `event_name` VARCHAR(120) NOT NULL, `event_version` INT NOT NULL DEFAULT 1, `payload_hash` CHAR(64) NOT NULL, `status` VARCHAR(24) NOT NULL, `attempt` INT NOT NULL DEFAULT 0, `processed_at` DATETIME(3) NULL, `last_error_code` VARCHAR(80) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_integration_idempotency_uuid_key` (`uuid`), UNIQUE KEY `system_integration_idempotency_identity_key` (`integration_id`,`event_key`,`event_name`,`event_version`), KEY `system_integration_idempotency_status_idx` (`integration_id`,`status`,`updated_at`)) ENGINE=InnoDB;
CREATE TABLE `system_operational_alert_rules` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `uuid` CHAR(36) NOT NULL, `rule_key` VARCHAR(160) NOT NULL, `signal` VARCHAR(80) NOT NULL, `severity` VARCHAR(16) NOT NULL, `threshold` INT NOT NULL DEFAULT 1, `window_seconds` INT NOT NULL DEFAULT 60, `cooldown_seconds` INT NOT NULL DEFAULT 300, `enabled` BOOLEAN NOT NULL DEFAULT true, `metadata` JSON NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `system_operational_alert_rules_uuid_key` (`uuid`), UNIQUE KEY `system_operational_alert_rules_rule_key_key` (`rule_key`), KEY `system_operational_alert_rules_enabled_signal_idx` (`enabled`,`signal`)) ENGINE=InnoDB;
